import { LedType } from "@/types/led";
import { error } from "console";
const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";
import fetchWithAuth from "../fetchWithAuth";

export interface MediaConverter {
  id: string; // Database ID (required for update)

  mediaConverterId: string;

  left1: boolean;
  left2: boolean;
  left3: boolean;

  right1: boolean;
  right2: boolean;
  right3: boolean;

  left1Label: string;
  left2Label: string;
  left3Label: string;

  right1Label: string;
  right2Label: string;
  right3Label: string;
}

export interface SmartMeter {
  id: string;

  smartMeterId: string;
  location?: string;
  ipAddress: string;

  latitude?: number;
  longitude?: number;

  status: string;
  addedBy: string;

  createdAt: string;
  updatedAt: string;

  sensors?: any[];
  mediaConverters?: MediaConverter[];
}

export interface CreateMediaConverter {
  mediaConverterId: string;

  left1Label: string;
  left2Label: string;
  left3Label: string;

  right1Label: string;
  right2Label: string;
  right3Label: string;
}

export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  count?: number;
  error?: string;
  message?: string;
}

export interface PaginationMeta {
  page: number;
  limit: number;
  totalCount: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export interface PaginatedApiResponse<T> {
  success: boolean;
  data?: T;
  pagination?: PaginationMeta;
  error?: string;
  message?: string;
}

/* ==================================================
   GET ALL SMART METERS
================================================== */

export async function getAllSmartMeters(params?: {
  status?: string;
  include?: boolean;
  page?: number;
  limit?: number;
  search?: string;
}): Promise<PaginatedApiResponse<SmartMeter[]>> {
  try {
    const queryParams = new URLSearchParams();

    if (params?.status) queryParams.append("status", params.status);

    if (params?.include) queryParams.append("include", "true");

    if (params?.page) queryParams.append("page", params.page.toString());

    if (params?.limit) queryParams.append("limit", params.limit.toString());

    if (params?.search) queryParams.append("search", params.search);

    const response = await fetchWithAuth(
      `${API_BASE_URL}/api/smartmeters${
        queryParams.toString() ? `?${queryParams.toString()}` : ""
      }`,
      {
        method: "GET",
        credentials: "include",
        cache: "no-store",
        headers: {
          "Content-Type": "application/json",
        },
      },
    );

    
    if (!response.ok) {
      const errorData = await response.json();
      console.log(errorData);

      throw new Error(errorData.error || "Failed to fetch Smart Meters");
    }

    return await response.json();
  } catch (error) {
    console.error("Error fetching Smart Meters:", error);

    return {
      success: false,
      error:
        error instanceof Error ? error.message : "Failed to fetch Smart Meters",
    };
  }
}

